namespace rcl_interfaces { namespace msg {
struct ParameterValue {
  static constexpr const char* TYPE = "rcl_interfaces/msg/ParameterValue";
  uint8_t type = 0;
  bool bool_value = false;
  int64_t integer_value = 0;
  double double_value = 0;
  msgcore::Str<48> string_value;
  msgcore::Seq<uint8_t, 8> byte_array_value;
  msgcore::Seq<bool, 8> bool_array_value;
  msgcore::Seq<int64_t, 8> integer_array_value;
  msgcore::Seq<double, 8> double_array_value;
  msgcore::Seq<msgcore::Str<40>, 16> string_array_value;
};
inline void cdr_write(cdr::Writer& w, const ParameterValue& m) {
  w.put(m.type);
  w.put(m.bool_value);
  w.put(m.integer_value);
  w.put(m.double_value);
  w.str(m.string_value.data);
  w.put(m.byte_array_value.size);
  w.array(m.byte_array_value.data, m.byte_array_value.size);
  w.put(m.bool_array_value.size);
  w.array(m.bool_array_value.data, m.bool_array_value.size);
  w.put(m.integer_array_value.size);
  w.array(m.integer_array_value.data, m.integer_array_value.size);
  w.put(m.double_array_value.size);
  w.array(m.double_array_value.data, m.double_array_value.size);
  w.put(m.string_array_value.size);
  for (uint32_t i = 0; i < m.string_array_value.size; i++) w.str(m.string_array_value[i].data);
}
inline void cdr_read(cdr::Reader& r, ParameterValue& m) {
  r.get(m.type);
  r.get(m.bool_value);
  r.get(m.integer_value);
  r.get(m.double_value);
  r.str(m.string_value.data, sizeof m.string_value.data);
  m.byte_array_value.size = r.count(m.byte_array_value.capacity);
  r.array(m.byte_array_value.data, m.byte_array_value.size);
  m.bool_array_value.size = r.count(m.bool_array_value.capacity);
  r.array(m.bool_array_value.data, m.bool_array_value.size);
  m.integer_array_value.size = r.count(m.integer_array_value.capacity);
  r.array(m.integer_array_value.data, m.integer_array_value.size);
  m.double_array_value.size = r.count(m.double_array_value.capacity);
  r.array(m.double_array_value.data, m.double_array_value.size);
  m.string_array_value.size = r.count(m.string_array_value.capacity);
  for (uint32_t i = 0; i < m.string_array_value.size; i++) r.str(m.string_array_value[i].data, sizeof m.string_array_value[i].data);
}
}}  // namespace rcl_interfaces::msg

